import Phaser from 'phaser';

export type Palette = Record<string, string>;

/**
 * Builds a canvas texture from character rows.
 * - '.' or ' ' = transparent, every other char is looked up in the palette.
 * - mirror: rows are LEFT halves; the right half is generated by mirroring.
 * Rows are padded/truncated to a uniform width so small authoring mistakes never crash.
 */
export function makeSprite(
  scene: Phaser.Scene,
  key: string,
  rows: string[],
  pal: Palette,
  opts: { mirror?: boolean; width?: number; patch?: [number, number, string][] } = {},
) {
  if (scene.textures.exists(key)) scene.textures.remove(key);
  let src = rows;
  if (opts.mirror) {
    const hw = Math.max(...rows.map((r) => r.length));
    src = rows.map((r) => {
      const half = r.padEnd(hw, '.').slice(0, hw);
      return half + half.split('').reverse().join('');
    });
  }
  const w = opts.width ?? Math.max(...src.map((r) => r.length));
  const h = src.length;
  const tex = scene.textures.createCanvas(key, w, h)!;
  const ctx = tex.getContext();
  for (let y = 0; y < h; y++) {
    const row = src[y].padEnd(w, '.');
    for (let x = 0; x < w; x++) {
      const c = row[x];
      if (c === '.' || c === ' ') continue;
      const col = pal[c];
      if (!col) continue;
      ctx.fillStyle = col;
      ctx.fillRect(x, y, 1, 1);
    }
  }
  // asymmetric details (e.g. a mole on one cheek) applied after mirroring
  for (const [x, y, col] of opts.patch ?? []) {
    ctx.fillStyle = col;
    ctx.fillRect(x, y, 1, 1);
  }
  tex.refresh();
  return tex;
}

/** Create a texture by drawing into a 2D canvas context. */
export function makeCanvas(scene: Phaser.Scene, key: string, w: number, h: number, draw: (ctx: CanvasRenderingContext2D) => void) {
  if (scene.textures.exists(key)) scene.textures.remove(key);
  const tex = scene.textures.createCanvas(key, w, h)!;
  const ctx = tex.getContext();
  ctx.imageSmoothingEnabled = false;
  draw(ctx);
  tex.refresh();
  return tex;
}

/** Pixel-perfect filled circle. */
export function pixCircle(ctx: CanvasRenderingContext2D, cx: number, cy: number, r: number, color: string) {
  ctx.fillStyle = color;
  for (let y = -r; y <= r; y++) {
    for (let x = -r; x <= r; x++) {
      if (x * x + y * y <= r * r + r * 0.6) ctx.fillRect(Math.round(cx + x), Math.round(cy + y), 1, 1);
    }
  }
}

/** Pixel-perfect circle outline. */
export function pixRing(ctx: CanvasRenderingContext2D, cx: number, cy: number, r: number, thick: number, color: string) {
  ctx.fillStyle = color;
  for (let y = -r; y <= r; y++) {
    for (let x = -r; x <= r; x++) {
      const d = Math.sqrt(x * x + y * y);
      if (d <= r + 0.3 && d >= r - thick + 0.3) ctx.fillRect(Math.round(cx + x), Math.round(cy + y), 1, 1);
    }
  }
}

export const R = (c: string, n: number) => c.repeat(Math.max(0, n));
